export default {"fps": 30, "width": 1920, "height": 1080, "total": 303.188, "audio": "measured", "chapters": [{"id": 1, "name": "第一章", "title": "山河危局", "start": 0.0}, {"id": 2, "name": "第二章", "title": "救亡图存", "start": 27.764}, {"id": 3, "name": "第三章", "title": "维新登场", "start": 83.575}, {"id": 4, "name": "第四章", "title": "百日新政", "start": 129.359}, {"id": 5, "name": "第五章", "title": "风暴将至", "start": 187.043}, {"id": 6, "name": "第六章", "title": "戊戌政变", "start": 230.555}, {"id": 7, "name": "第七章", "title": "历史回响", "start": 272.69}], "scenes": [{"id": "S01_war_map", "chapter": 1, "start": 0.0, "dur": 9.743, "cues": [{"text": "1894年，中日甲午战争爆发", "start": 1.728, "end": 4.332, "line": 0}, {"text": "次年，北洋舰队全军覆没", "start": 4.692, "end": 6.848, "line": 1}, {"text": "清政府被迫签订《马关条约》", "start": 6.968, "end": 9.347, "line": 1}]}, {"id": "S02_treaty", "chapter": 1, "start": 9.743, "dur": 4.014, "cues": [{"text": "割让台湾、澎湖，赔款白银二亿两", "start": 0.144, "end": 2.646, "line": 0}]}, {"id": "S03_hook", "chapter": 1, "start": 13.757, "dur": 7.407, "cues": [{"text": "1898年，一场试图改变中国命运的改革", "start": 0.36, "end": 3.865, "line": 0}, {"text": "为何只持续了103天？", "start": 4.045, "end": 6.183, "line": 1}]}, {"id": "S04_title", "chapter": 1, "start": 21.164, "dur": 6.6, "cues": []}, {"id": "S05_old_city", "chapter": 2, "start": 27.764, "dur": 8.234, "cues": [{"text": "甲午之败，震动朝野", "start": 1.152, "end": 2.864, "line": 0}, {"text": "泱泱大国败于东邻日本", "start": 3.224, "end": 5.142, "line": 1}, {"text": "“天朝上国”的迷梦就此破碎", "start": 5.262, "end": 7.586, "line": 1}]}, {"id": "S06_partition", "chapter": 2, "start": 35.998, "dur": 11.829, "cues": [{"text": "列强随即掀起瓜分中国的狂潮", "start": 0.288, "end": 3.077, "line": 0}, {"text": "1897年，德国强占胶州湾", "start": 3.257, "end": 5.823, "line": 1}, {"text": "次年，俄国强租旅顺、大连", "start": 6.003, "end": 8.115, "line": 2}, {"text": "英、法等国也纷纷划分势力范围", "start": 8.235, "end": 10.893, "line": 2}]}, {"id": "S07_jiuwang", "chapter": 2, "start": 47.827, "dur": 5.187, "cues": [{"text": "民族危机空前深重", "start": 0.216, "end": 1.915, "line": 0}, {"text": "“救亡图存”成为时代的呼声", "start": 2.035, "end": 4.251, "line": 0}]}, {"id": "S08_gongche", "chapter": 2, "start": 53.014, "dur": 15.569, "cues": [{"text": "1895年春，康有为联合在京参加会试的举人，起草上书", "start": 0.216, "end": 4.839, "line": 0}, {"text": "主张拒和、迁都、练兵、变法，史称“公车上书”", "start": 5.019, "end": 8.427, "line": 1}, {"text": "不过，关于参与人数和上书是否真正递交", "start": 8.787, "end": 12.332, "line": 2}, {"text": "史学界至今仍有不同看法", "start": 12.452, "end": 14.777, "line": 2}]}, {"id": "S09_press", "chapter": 2, "start": 68.583, "dur": 14.992, "cues": [{"text": "此后，维新人士纷纷组织学会、创办报刊", "start": 0.216, "end": 3.442, "line": 0}, {"text": "梁启超在上海主笔《时务报》", "start": 3.622, "end": 5.953, "line": 1}, {"text": "严复在天津参与创办《国闻报》，译述《天演论》", "start": 6.073, "end": 9.399, "line": 1}, {"text": "“变法”二字，从士大夫的书斋", "start": 9.759, "end": 11.888, "line": 2}, {"text": "走向了更广阔的社会", "start": 12.008, "end": 13.912, "line": 2}]}, {"id": "S10_reformers", "chapter": 3, "start": 83.575, "dur": 19.616, "cues": [{"text": "维新运动的核心人物", "start": 1.152, "end": 2.845, "line": 0}, {"text": "是康有为、梁启超和谭嗣同", "start": 2.965, "end": 5.337, "line": 0}, {"text": "康有为著《新学伪经考》《孔子改制考》，借孔子之名，为变法立论", "start": 5.697, "end": 10.344, "line": 1}, {"text": "他的学生梁启超，以一支健笔", "start": 10.524, "end": 12.812, "line": 2}, {"text": "让变法主张传遍全国", "start": 12.932, "end": 15.018, "line": 2}, {"text": "谭嗣同著《仁学》，猛烈抨击束缚人心的纲常名教", "start": 15.198, "end": 18.968, "line": 3}]}, {"id": "S11_guangxu", "chapter": 3, "start": 103.191, "dur": 5.206, "cues": [{"text": "而真正把变法推上朝堂的", "start": 0.216, "end": 2.575, "line": 0}, {"text": "是年轻的光绪皇帝", "start": 2.695, "end": 4.486, "line": 0}]}, {"id": "S12_palace", "chapter": 3, "start": 108.397, "dur": 6.548, "cues": [{"text": "1898年6月11日", "start": 0.864, "end": 2.685, "line": 0}, {"text": "光绪帝颁布《明定国是诏》，宣布变法", "start": 2.805, "end": 5.756, "line": 0}]}, {"id": "S13_edict", "chapter": 3, "start": 114.945, "dur": 6.825, "cues": [{"text": "诏书要求在坚守圣贤义理的同时", "start": 0.432, "end": 3.337, "line": 0}, {"text": "“博采西学之切于时务者”", "start": 3.457, "end": 5.457, "line": 0}]}, {"id": "S14_timeline", "chapter": 3, "start": 121.77, "dur": 7.589, "cues": [{"text": "五天后，光绪帝在颐和园召见康有为", "start": 0.216, "end": 3.261, "line": 0}, {"text": "一场自上而下的变革，就此拉开序幕", "start": 3.621, "end": 6.509, "line": 1}]}, {"id": "S15_edicts", "chapter": 4, "start": 129.359, "dur": 6.331, "cues": [{"text": "此后的一百多天里", "start": 1.152, "end": 2.744, "line": 0}, {"text": "光绪帝接连颁布上百道新政诏令", "start": 2.864, "end": 5.683, "line": 0}]}, {"id": "S16_politics", "chapter": 4, "start": 135.69, "dur": 8.516, "cues": [{"text": "政治上，裁撤詹事府、通政司等闲散衙门，裁汰冗员", "start": 0.216, "end": 4.323, "line": 0}, {"text": "允许各级官员和士民上书言事，疏通言路", "start": 4.503, "end": 7.724, "line": 1}]}, {"id": "S17_education", "chapter": 4, "start": 144.206, "dur": 14.639, "cues": [{"text": "教育上，废除八股取士", "start": 0.216, "end": 2.097, "line": 0}, {"text": "乡试、会试改试策论", "start": 2.217, "end": 3.94, "line": 0}, {"text": "需要强调的是，这并不是废除科举", "start": 4.3, "end": 7.04, "line": 1}, {"text": "——科举制度直到1905年才被正式废止", "start": 7.16, "end": 10.474, "line": 1}, {"text": "各地书院，则改为兼习中学、西学的学堂", "start": 10.834, "end": 13.847, "line": 2}]}, {"id": "S18_university", "chapter": 4, "start": 158.845, "dur": 15.306, "cues": [{"text": "这一时期创办的京师大学堂", "start": 0.288, "end": 2.661, "line": 0}, {"text": "既是全国最高学府", "start": 2.781, "end": 4.566, "line": 0}, {"text": "也是统辖各省学堂的教育行政机关", "start": 4.686, "end": 7.69, "line": 0}, {"text": "政变之后，它作为少数保留下来的新政成果继续开办", "start": 8.05, "end": 12.428, "line": 1}, {"text": "后来发展为北京大学", "start": 12.548, "end": 14.37, "line": 1}]}, {"id": "S19_economy", "chapter": 4, "start": 174.151, "dur": 6.706, "cues": [{"text": "经济上，设立农工商总局和矿务铁路总局，提倡实业", "start": 0.216, "end": 4.407, "line": 0}, {"text": "奖励发明创造", "start": 4.527, "end": 5.914, "line": 0}]}, {"id": "S20_military", "chapter": 4, "start": 180.857, "dur": 6.186, "cues": [{"text": "军事上，裁减旧式军队，改练洋操", "start": 0.216, "end": 3.015, "line": 0}, {"text": "倡导以西法训练新式军队", "start": 3.135, "end": 5.394, "line": 0}]}, {"id": "S22_resistance", "chapter": 5, "start": 187.043, "dur": 19.883, "cues": [{"text": "然而，变法的阻力从一开始就存在", "start": 1.152, "end": 3.966, "line": 0}, {"text": "诏令雪片般下达", "start": 4.326, "end": 6.001, "line": 1}, {"text": "许多地方督抚却观望拖延", "start": 6.121, "end": 8.512, "line": 1}, {"text": "裁撤衙门、改革科举", "start": 8.692, "end": 10.384, "line": 2}, {"text": "又触动了大批官员和读书人的切身利益", "start": 10.504, "end": 13.759, "line": 2}, {"text": "新政推行仓促，官僚体系执行乏力", "start": 14.119, "end": 16.996, "line": 3}, {"text": "许多措施停留在纸面上", "start": 17.116, "end": 19.235, "line": 3}]}, {"id": "S23_power", "chapter": 5, "start": 206.926, "dur": 13.36, "cues": [{"text": "更关键的是，光绪帝并未掌握实权", "start": 0.216, "end": 3.135, "line": 0}, {"text": "变法开始仅四天", "start": 3.495, "end": 5.128, "line": 1}, {"text": "帝师翁同龢便被开缺回籍", "start": 5.248, "end": 7.516, "line": 1}, {"text": "慈禧太后的亲信荣禄出任直隶总督", "start": 7.636, "end": 10.676, "line": 1}, {"text": "掌握京畿一带的兵权", "start": 10.796, "end": 12.64, "line": 1}]}, {"id": "S24_corridor", "chapter": 5, "start": 220.286, "dur": 10.269, "cues": [{"text": "9月初，光绪帝罢免阻挠上书的礼部六堂官", "start": 0.288, "end": 3.852, "line": 0}, {"text": "又任命谭嗣同等四人为军机章京", "start": 3.972, "end": 6.831, "line": 0}, {"text": "帝后之间的矛盾迅速激化", "start": 6.951, "end": 9.189, "line": 0}]}, {"id": "S25_coup", "chapter": 6, "start": 230.555, "dur": 11.183, "cues": [{"text": "1898年9月21日", "start": 1.296, "end": 3.488, "line": 0}, {"text": "慈禧太后宣布重新“训政”", "start": 3.608, "end": 6.065, "line": 0}, {"text": "光绪帝随后被幽禁于中南海瀛台，史称“戊戌政变”", "start": 6.185, "end": 10.391, "line": 0}]}, {"id": "S26_exile", "chapter": 6, "start": 241.738, "dur": 3.664, "cues": [{"text": "康有为、梁启超先后流亡海外", "start": 0.144, "end": 2.728, "line": 0}]}, {"id": "S27_six", "chapter": 6, "start": 245.402, "dur": 10.303, "cues": [{"text": "9月28日", "start": 0.288, "end": 1.661, "line": 0}, {"text": "谭嗣同、林旭、杨锐、刘光第、杨深秀、康广仁六人在北京菜市口遇害", "start": 1.781, "end": 7.142, "line": 0}, {"text": "史称“戊戌六君子”", "start": 7.262, "end": 8.935, "line": 0}]}, {"id": "S28_poem", "chapter": 6, "start": 255.705, "dur": 10.203, "cues": [{"text": "据梁启超记述，谭嗣同拒绝出走", "start": 0.216, "end": 3.03, "line": 0}, {"text": "并在狱中题壁写道", "start": 3.15, "end": 4.951, "line": 0}, {"text": "“我自横刀向天笑", "start": 5.131, "end": 6.887, "line": 1}, {"text": "去留肝胆两昆仑。”", "start": 7.007, "end": 8.691, "line": 1}]}, {"id": "S29_aftermath", "chapter": 6, "start": 265.908, "dur": 6.782, "cues": [{"text": "新政措施，除京师大学堂等少数几项外", "start": 0.216, "end": 3.836, "line": 0}, {"text": "几乎全部被废止", "start": 3.956, "end": 5.702, "line": 0}]}, {"id": "S30_echo", "chapter": 7, "start": 272.69, "dur": 11.747, "cues": [{"text": "戊戌变法失败了", "start": 1.152, "end": 2.681, "line": 0}, {"text": "但它推动了思想启蒙", "start": 2.981, "end": 4.961, "line": 0}, {"text": "使政治改革成为公开讨论的议题", "start": 5.081, "end": 8.038, "line": 0}, {"text": "也为中国近代教育播下了种子", "start": 8.158, "end": 10.955, "line": 0}]}, {"id": "S31_final", "chapter": 7, "start": 284.437, "dur": 9.251, "cues": [{"text": "103天，未能改变一个王朝的命运", "start": 0.288, "end": 3.397, "line": 0}, {"text": "却成为中国近代变革历程中无法绕过的一页", "start": 3.577, "end": 7.451, "line": 1}]}, {"id": "S32_credits", "chapter": 7, "start": 293.688, "dur": 9.5, "cues": []}]};
